WITH with_last AS (SELECT s.id, s.store_name, s.city, s.region, s.opened_date, s.sqft, top1.amount, top1.channel FROM stores s LEFT JOIN LATERAL (SELECT c.amount, c.channel FROM orders c WHERE c.store_id = s.id ORDER BY c.order_date DESC, c.id DESC LIMIT 1) top1 ON TRUE), scored AS (SELECT *, NTILE(3) OVER (PARTITION BY channel ORDER BY sqft DESC, id) AS sqft_bucket, SUM(sqft) OVER (PARTITION BY channel ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sqft, AVG(sqft) OVER (PARTITION BY channel, region) AS channel_avg_sqft FROM with_last), eligible AS (SELECT s.* FROM scored s WHERE NOT EXISTS (SELECT 1 FROM store_sales x WHERE x.store_id = s.id AND x.revenue IS NOT NULL)), not_flagged AS (SELECT s.* FROM eligible s WHERE NOT EXISTS (SELECT 1 FROM orders x WHERE x.store_id = s.id AND x.order_date >= s.opened_date)) SELECT id, store_name, city, region, opened_date, sqft, amount, channel, sqft_bucket FROM not_flagged ORDER BY sqft_bucket DESC;
